'use strict';

let adminCache = { buildings: [], branches: [], departments: [], services: [], calendars: [] };

function activeBadge(active) {
  return `<span class="badge ${Number(active) ? 'green' : 'amber'}">${Number(active) ? 'เปิดใช้งาน' : 'ปิดใช้งาน'}</span>`;
}

async function loadAdminData() {
  const [buildings, branches, departments, services, calendars] = await Promise.all([
    kqApi('buildings'), kqApi('branches'), kqApi('departments'), kqApi('services'), kqApi('calendars')
  ]);
  adminCache = {buildings: buildings.data, branches: branches.data, departments: departments.data, services: services.data, calendars: calendars.data};
}

async function renderOrganizationPage() {
  try {
    await loadAdminData();
    document.getElementById('viewContent').innerHTML = `<div class="page-card">
      <div class="page-toolbar"><div><h2>แผนก</h2><p>กำหนดวันเปิด เวลา จำนวนรับ และช่วง Slot ของแต่ละแผนก โดยระบบจัดการโครงสร้างพื้นฐานให้อัตโนมัติ</p></div><button class="primary" data-crud-add="department">＋ เพิ่มแผนก</button></div>
      <section class="admin-section"><div class="section-title"><div><h3>แผนกทั้งหมด</h3><p>ตั้งค่าครั้งเดียว ระบบสร้าง Slot เฉพาะวันที่แผนกเปิด</p></div></div>
        ${simpleTable(['รหัสคิว','แผนก','จำนวนรับ/วัน','แบ่งช่วง','สถานะ',''],adminCache.departments.map(item=>[escapeHtml(item.code),escapeHtml(item.name),Number(item.unlimited_capacity)?'<span class="badge blue">ไม่จำกัดคิว</span>':item.daily_capacity?`${item.daily_capacity} คน`:'ใช้ค่าเดิม',item.slot_minutes?`${item.slot_minutes} นาที`:'ไม่แบ่งช่วง',activeBadge(item.active),`<div class="action-cell"><button class="record-button" data-crud-edit="department" data-id="${item.id}">แก้ไข</button><button class="record-button" data-schedule="DEPARTMENT" data-id="${item.id}" data-name="${escapeHtml(item.name)}">วันและเวลาเปิด</button></div>`]),adminCache.departments)}
      </section></div>`;
    document.querySelectorAll('[data-crud-edit="department"]').forEach(button=>{const slotButton=document.createElement('button');slotButton.type='button';slotButton.className='record-button';slotButton.dataset.slotRules=button.dataset.id;slotButton.textContent='กำหนด Slot';button.closest('.action-cell')?.appendChild(slotButton)});
  } catch (error) { showToast(error.message); }
}

async function renderServicesPage() {
  try {
    await loadAdminData();
    document.getElementById('viewContent').innerHTML = `<div class="page-card"><div class="page-toolbar"><div><h2>ประเภทบริการ</h2><p>ผูกชื่อบริการกับแผนก ส่วน Slot และจำนวนรับกำหนดที่แผนก</p></div><button class="primary" data-crud-add="service">＋ เพิ่มบริการ</button></div>${simpleTable(['รหัส','บริการ','แผนก','สถานะ',''],adminCache.services.map(item=>[escapeHtml(item.code),escapeHtml(item.name),escapeHtml(item.department_name),activeBadge(item.active),`<button class="record-button" data-crud-edit="service" data-id="${item.id}">แก้ไข</button>`]),adminCache.services)}</div>`;
  } catch (error) { showToast(error.message); }
}

async function renderCalendarPage() {
  try {
    await loadAdminData();
    document.getElementById('viewContent').innerHTML = `<div class="page-card"><div class="page-toolbar"><div><h2>ปฏิทินทำการ</h2><p>กำหนดวันปิดหรือเวลาให้บริการพิเศษรายแผนก</p></div><div class="calendar-toolbar-actions"><button class="secondary" data-hosxp-holiday-sync>↻ Sync วันหยุด HOSxP</button><button class="primary" data-crud-add="calendar">＋ เพิ่มวันพิเศษ</button></div></div>${simpleTable(['วันที่','รายการ','ใช้กับ','เวลาทำการ','หมายเหตุ','สถานะ',''],adminCache.calendars.map(item=>[`<div class="calendar-date">${KQThaiDate.date(item.override_date,{month:'short'})}</div>`,escapeHtml(item.name),item.scope_type==='BRANCH'?'วันหยุดทั้งระบบ':escapeHtml(item.scope_name||'-'),Number(item.is_closed)?'<span class="badge amber">ปิดบริการ</span>':`${item.open_time}–${item.close_time} น.`,escapeHtml(item.note||'-'),activeBadge(item.active),item.scope_type==='BRANCH'?'—':`<button class="record-button" data-crud-edit="calendar" data-id="${item.id}">แก้ไข</button>`]),adminCache.calendars)}</div>`;
  } catch (error) { showToast(error.message); }
}

function simpleTable(headers, rows, records=[]) {
  return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map((row,index)=>`<tr class="${records[index]&&!Number(records[index].active)?'inactive-row':''}">${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">ยังไม่มีข้อมูล</td></tr>`}</tbody></table></div>`;
}

function branchOptions(selected='') { return adminCache.branches.map(item=>`<option value="${item.id}" ${String(item.id)===String(selected)?'selected':''}>${escapeHtml(item.name)}</option>`).join(''); }
function departmentOptions(selected='') { return adminCache.departments.map(item=>`<option value="${item.id}" ${String(item.id)===String(selected)?'selected':''}>${escapeHtml(item.name)} · ${escapeHtml(item.branch_name)}</option>`).join(''); }
function buildingOptions(selected='') { return adminCache.buildings.map(item=>`<option value="${item.id}" ${String(item.id)===String(selected)?'selected':''}>${escapeHtml(item.name)}</option>`).join(''); }

function openCrudDialog(type, record={}) {
  const isEdit=Boolean(record.id); let title=''; let fields='';
  if(type==='building'){title=isEdit?'แก้ไขอาคาร':'เพิ่มอาคาร';fields=`<label>รหัสอาคาร<input name="code" value="${escapeHtml(record.code||'')}" required pattern="[A-Za-z0-9_-]{2,20}"></label><label>ชื่ออาคาร<input name="name" value="${escapeHtml(record.name||'')}" required></label><label class="toggle-label full"><input name="is_24_hours" type="checkbox" ${Number(record.is_24_hours)?'checked':''}> อาคารเปิด 24 ชั่วโมง</label><label class="building-time">เวลาเปิด<input name="open_time" type="time" value="${record.open_time||'06:00'}"></label><label class="building-time">เวลาปิด<input name="close_time" type="time" value="${record.close_time||'22:00'}"></label>`;}
  if(type==='branch'){title=isEdit?'แก้ไขสาขา':'เพิ่มสาขา';fields=`<label>อาคาร<select name="building_id" required>${buildingOptions(record.building_id)}</select></label><label>รหัสสาขา<input name="code" value="${escapeHtml(record.code||'')}" required pattern="[A-Za-z0-9_-]{2,20}"></label><label>ชื่อสาขา<input name="name" value="${escapeHtml(record.name||'')}" required></label><label>เวลาเปิดพื้นฐาน<input name="open_time" type="time" value="${record.open_time||'08:30'}" required></label><label>เวลาปิดพื้นฐาน<input name="close_time" type="time" value="${record.close_time||'20:00'}" required></label><label>Closing buffer (นาที)<input name="closing_buffer_minutes" type="number" min="0" max="180" value="${record.closing_buffer_minutes??30}" required></label>`;}
  if(type==='department'){title=isEdit?'แก้ไขแผนก':'เพิ่มแผนก';fields=`<label>สาขา<select name="branch_id" required>${branchOptions(record.branch_id)}</select></label><label>รหัสแผนก<input name="code" value="${escapeHtml(record.code||'')}" required pattern="[A-Za-z0-9_-]{2,20}"></label><label>ชื่อแผนก<input name="name" value="${escapeHtml(record.name||'')}" required></label><label>จำนวนรับรวมต่อวัน<input name="daily_capacity" type="number" min="1" max="10000" value="${record.daily_capacity??''}" placeholder="เช่น 80" required></label><label class="toggle-label"><input name="unlimited_capacity" type="checkbox" ${Number(record.unlimited_capacity)?'checked':''}> ไม่จำกัดจำนวนคิว</label><label>แบ่งช่วง Slot<select name="slot_minutes"><option value="" ${!record.slot_minutes?'selected':''}>ไม่กำหนด — ใช้เวลาทำการทั้งช่วง</option>${[15,30,45,60,90,120].map(v=>`<option value="${v}" ${Number(record.slot_minutes)===v?'selected':''}>ทุก ${v} นาที</option>`).join('')}</select></label><input name="counter_count" type="hidden" value="${record.counter_count??1}"><input name="efficiency" type="hidden" value="${record.efficiency??.8}"><input name="online_quota_percent" type="hidden" value="${record.online_quota_percent??70}"><input name="walkin_quota_percent" type="hidden" value="${record.walkin_quota_percent??20}"><input name="reserve_quota_percent" type="hidden" value="${record.reserve_quota_percent??10}"><p class="full form-help">เมื่อเลือกไม่จำกัดคิว ระบบจะไม่ปิดรับจากจำนวนคิว แต่ยังยึดวัน เวลา และสถานะเปิดบริการตามที่ตั้งค่า</p>`;}
  if(type==='service'){title=isEdit?'แก้ไขบริการ':'เพิ่มบริการ';fields=`<label>แผนก<select name="department_id" required>${departmentOptions(record.department_id)}</select></label><label>รหัสบริการ<input name="code" value="${escapeHtml(record.code||'')}" required pattern="[A-Za-z0-9_-]{2,30}"></label><label>ชื่อบริการ<input name="name" value="${escapeHtml(record.name||'')}" required></label><label>เวลาเฉลี่ยต่อคิว (ข้อมูลประกอบ)<input name="average_minutes" type="number" min="1" max="480" value="${record.average_minutes??15}" required></label><label>เวลาเตรียมงาน (ข้อมูลประกอบ)<input name="preparation_minutes" type="number" min="0" max="120" value="${record.preparation_minutes??0}" required></label><input name="slot_minutes" type="hidden" value="${record.slot_minutes??30}"><input name="default_capacity" type="hidden" value="${record.default_capacity??1}">`;}
  if(type==='calendar'){title=isEdit?'แก้ไขวันพิเศษ':'เพิ่มวันพิเศษ';fields=`<label>ระดับ<select name="scope_type"><option value="BRANCH" ${record.scope_type==='BRANCH'?'selected':''}>สาขา</option><option value="DEPARTMENT" ${record.scope_type==='DEPARTMENT'?'selected':''}>แผนก</option></select></label><label>หน่วยบริการ<select name="scope_id" required></select></label><label>วันที่ (พ.ศ.)<select name="override_date" required>${KQThaiDate.options(record.override_date||KQThaiDate.todayISO(),365,730)}</select></label><label>ชื่อรายการ<input name="name" value="${escapeHtml(record.name||'')}" required></label><label class="toggle-label full"><input name="is_closed" type="checkbox" ${Number(record.is_closed)?'checked':''}> ปิดบริการทั้งวัน</label><label class="calendar-time">เวลาเปิด<input name="open_time" type="time" value="${record.open_time||'08:30'}"></label><label class="calendar-time">เวลาปิด<input name="close_time" type="time" value="${record.close_time||'20:00'}"></label><label class="calendar-time">จำนวนจุดบริการประจำวัน (ข้อมูลประกอบ)<input name="counter_count" type="number" min="1" value="${record.counter_count||''}"></label><label class="full">หมายเหตุ<textarea name="note">${escapeHtml(record.note||'')}</textarea></label>`;}
  const wrapper=document.createElement('div');wrapper.className='crud-backdrop';wrapper.innerHTML=`<form class="crud-dialog" data-type="${type}"><header><div><span class="eyebrow">K-QCENTER ADMIN</span><h2>${title}</h2></div><button type="button" class="icon-button" data-dialog-close>×</button></header><input type="hidden" name="id" value="${record.id||''}"><div class="crud-form-grid">${fields}<label class="toggle-label full"><input name="active" type="checkbox" ${record.active===undefined||Number(record.active)?'checked':''}> เปิดใช้งานรายการนี้</label></div><div class="auth-error hidden" data-form-error></div><div class="dialog-actions"><button type="button" class="secondary" data-dialog-close>ยกเลิก</button><button type="submit" class="primary">บันทึกข้อมูล</button></div></form>`;document.body.appendChild(wrapper);
  if(type==='department'){const branch=wrapper.querySelector('[name="branch_id"]');branch.closest('label').classList.add('hidden');if(!branch.value&&adminCache.branches[0])branch.value=adminCache.branches[0].id;const code=wrapper.querySelector('[name="code"]'),label=code.closest('label');code.pattern='[A-Za-z0-9]{1,4}';code.minLength=1;code.maxLength=4;code.placeholder='เช่น NCD';label.firstChild.textContent='รหัสแผนก (ใช้ขึ้นต้นเลขคิว)';label.insertAdjacentHTML('beforeend','<small>อักษรอังกฤษหรือตัวเลข 1–4 ตัว เช่น NCD-001</small>')}if(type==='calendar'){const scope=wrapper.querySelector('[name="scope_type"]');scope.value='DEPARTMENT';scope.closest('label').classList.add('hidden')}
  const closed=wrapper.querySelector('[name="is_closed"]');if(closed){const toggle=()=>wrapper.querySelectorAll('.calendar-time').forEach(x=>x.classList.toggle('hidden',closed.checked));closed.onchange=toggle;toggle();}const is24=wrapper.querySelector('[name="is_24_hours"]');if(is24){const toggle=()=>wrapper.querySelectorAll('.building-time').forEach(x=>x.classList.toggle('hidden',is24.checked));is24.onchange=toggle;toggle();}const unlimited=wrapper.querySelector('[name="unlimited_capacity"]');if(unlimited){const capacity=wrapper.querySelector('[name="daily_capacity"]');const toggle=()=>{capacity.disabled=unlimited.checked;capacity.required=!unlimited.checked};unlimited.onchange=toggle;toggle();}const scope=wrapper.querySelector('[name="scope_type"]');if(scope){const target=wrapper.querySelector('[name="scope_id"]');const fill=()=>{const list=scope.value==='BRANCH'?adminCache.branches:adminCache.departments;target.innerHTML=list.map(item=>`<option value="${item.id}" ${String(item.id)===String(record.scope_id)?'selected':''}>${escapeHtml(item.name)}</option>`).join('')};scope.onchange=fill;fill();}
  wrapper.querySelectorAll('[data-dialog-close]').forEach(button=>button.onclick=()=>wrapper.remove());wrapper.querySelector('form').onsubmit=event=>submitCrud(event,wrapper,type);
}

async function submitCrud(event, wrapper, type) {
  event.preventDefault();const form=event.currentTarget;const values=Object.fromEntries(new FormData(form));values.active=form.elements.active.checked;values.id=values.id?Number(values.id):0;if(type==='calendar')values.is_closed=form.elements.is_closed.checked;if(type==='building')values.is_24_hours=form.elements.is_24_hours.checked;if(type==='department')values.unlimited_capacity=form.elements.unlimited_capacity.checked;const errorBox=wrapper.querySelector('[data-form-error]');errorBox.classList.add('hidden');
  try{await kqApi(`save-${type}`,{method:'POST',body:JSON.stringify(values)});wrapper.remove();showToast('บันทึกข้อมูลเรียบร้อย');if(['building','branch','department'].includes(type))await renderOrganizationPage();if(type==='service')await renderServicesPage();if(type==='calendar')await renderCalendarPage();}
  catch(error){errorBox.textContent=error.message;errorBox.classList.remove('hidden');}
}

function parseSlotConfig(record){try{const value=JSON.parse(record.custom_slot_config||'{}');return {enabled:Boolean(value.enabled),rules:Array.isArray(value.rules)?value.rules:[]}}catch{return {enabled:false,rules:[]}}}
function openSlotRulesDialog(record){
  const config=parseSlotConfig(record),days=['จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์','อาทิตย์'];
  const wrapper=document.createElement('div');wrapper.className='crud-backdrop';wrapper.innerHTML=`<form class="crud-dialog slot-rules-dialog"><header><div><span class="eyebrow">CUSTOM SLOT</span><h2>กำหนดช่วงเวลา Slot · ${escapeHtml(record.name)}</h2></div><button type="button" class="icon-button" data-dialog-close>×</button></header><label class="toggle-label slot-rule-enable"><input type="checkbox" name="enabled" ${config.enabled?'checked':''}> เปิดใช้ Slot แบบกำหนดเอง</label><p class="form-help">ระบบใช้กฎจากบนลงล่าง โดยเลือกกฎแรกที่ตรงกับวันและสัปดาห์ของเดือน วันที่เป็นวันหยุดหรือวันที่แผนกปิดจะไม่สร้าง Slot</p><div class="slot-rule-list"></div><button type="button" class="secondary slot-add-rule" data-add-rule>＋ เพิ่มกฎวันและช่วงเวลา</button><div class="auth-error hidden" data-form-error></div><div class="dialog-actions"><button type="button" class="secondary" data-dialog-close>ยกเลิก</button><button type="submit" class="primary">บันทึกกฎ Slot</button></div></form>`;document.body.appendChild(wrapper);
  const list=wrapper.querySelector('.slot-rule-list');
  const addPeriod=(container,period={})=>{const row=document.createElement('div');row.className='slot-rule-period';const unlimited=Boolean(period.unlimited);row.innerHTML=`<label>เวลาเริ่ม<input type="time" data-start value="${period.start_time||'07:30'}" required></label><label>เวลาสิ้นสุด<input type="time" data-end value="${period.end_time||'08:30'}" required></label><label>จำนวนคิว<input type="number" data-capacity min="1" max="10000" value="${period.capacity??40}" ${unlimited?'disabled':''} required></label><label class="slot-period-unlimited"><input type="checkbox" data-unlimited ${unlimited?'checked':''}> ไม่จำกัดคิว</label><button type="button" class="record-button" data-remove-period>ลบ</button>`;const unlimitedInput=row.querySelector('[data-unlimited]'),capacity=row.querySelector('[data-capacity]');unlimitedInput.onchange=()=>{capacity.disabled=unlimitedInput.checked;capacity.required=!unlimitedInput.checked};row.querySelector('[data-remove-period]').onclick=()=>row.remove();container.appendChild(row)};
  const addRule=(rule={})=>{const card=document.createElement('section');card.className='slot-rule-card';const weekdays=(rule.weekdays||[]).map(Number),weeks=(rule.weeks||[]).map(Number);card.innerHTML=`<div class="slot-rule-head"><label>ชื่อกฎ<input data-rule-name value="${escapeHtml(rule.name||'กฎช่วงเวลาบริการ')}" required></label><button type="button" class="record-button" data-remove-rule>ลบกฎ</button></div><fieldset><legend>วันที่ใช้กฎ</legend><div class="slot-check-grid">${days.map((day,index)=>`<label><input type="checkbox" data-weekday value="${index+1}" ${weekdays.includes(index+1)?'checked':''}> ${day}</label>`).join('')}</div></fieldset><fieldset><legend>สัปดาห์ที่ของเดือน <small>ไม่เลือก = ทุกสัปดาห์</small></legend><div class="slot-check-grid weeks">${[1,2,3,4,5].map(week=>`<label><input type="checkbox" data-week value="${week}" ${weeks.includes(week)?'checked':''}> สัปดาห์ที่ ${week}</label>`).join('')}</div></fieldset><div class="slot-period-head"><strong>ช่วงเวลาและจำนวนรับ</strong><button type="button" class="mini-button" data-add-period>＋ เพิ่มช่วง</button></div><div class="slot-rule-periods"></div>`;card.querySelector('[data-remove-rule]').onclick=()=>card.remove();card.querySelector('[data-add-period]').onclick=()=>addPeriod(card.querySelector('.slot-rule-periods'));const periods=rule.periods?.length?rule.periods:[{}];periods.forEach(period=>addPeriod(card.querySelector('.slot-rule-periods'),period));list.appendChild(card)};
  (config.rules.length?config.rules:[{}]).forEach(addRule);wrapper.querySelector('[data-add-rule]').onclick=()=>addRule({});wrapper.querySelectorAll('[data-dialog-close]').forEach(button=>button.onclick=()=>wrapper.remove());
  wrapper.querySelector('form').onsubmit=async event=>{event.preventDefault();const error=wrapper.querySelector('[data-form-error]');error.classList.add('hidden');const rules=[...list.querySelectorAll('.slot-rule-card')].map(card=>({name:card.querySelector('[data-rule-name]').value.trim(),weekdays:[...card.querySelectorAll('[data-weekday]:checked')].map(input=>Number(input.value)),weeks:[...card.querySelectorAll('[data-week]:checked')].map(input=>Number(input.value)),periods:[...card.querySelectorAll('.slot-rule-period')].map(row=>({start_time:row.querySelector('[data-start]').value,end_time:row.querySelector('[data-end]').value,capacity:Number(row.querySelector('[data-capacity]').value),unlimited:row.querySelector('[data-unlimited]').checked}))}));try{await kqApi('save-department-slot-rules',{method:'POST',body:JSON.stringify({department_id:Number(record.id),enabled:event.currentTarget.elements.enabled.checked,rules})});wrapper.remove();showToast('บันทึกกฎ Slot เรียบร้อยแล้ว');await renderOrganizationPage()}catch(err){error.textContent=err.message;error.classList.remove('hidden')}};
}

async function openScheduleDialog(scopeType,scopeId,scopeName){
  try{
    const response=await fetch(`${KQ_API}?action=weekly-hours&scope_type=${encodeURIComponent(scopeType)}&scope_id=${encodeURIComponent(scopeId)}`,{credentials:'same-origin'});const result=await response.json();if(!response.ok)throw new Error(result.error||'โหลดตารางเวลาไม่สำเร็จ');const days=['จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์','อาทิตย์'];
    const wrapper=document.createElement('div');wrapper.className='crud-backdrop';wrapper.innerHTML=`<form class="crud-dialog schedule-dialog"><header><div><span class="eyebrow">ตารางรายสัปดาห์</span><h2>${escapeHtml(scopeName)}</h2></div><button type="button" class="icon-button" data-dialog-close>×</button></header><p style="font-size:11px;color:var(--muted)">วันที่ไม่มีช่วงเวลาจะถือว่าปิด สามารถเพิ่มหลายช่วงเพื่อเว้นพักกลางวัน</p><div class="schedule-days">${days.map((day,index)=>`<section class="schedule-day" data-day="${index+1}"><div><strong>${day}</strong><button type="button" class="mini-button" data-add-period>＋ ช่วงเวลา</button></div><div class="period-list"></div></section>`).join('')}</div><div class="auth-error hidden" data-form-error></div><div class="dialog-actions"><button type="button" class="secondary" data-dialog-close>ยกเลิก</button><button type="submit" class="primary">บันทึกตารางเวลา</button></div></form>`;document.body.appendChild(wrapper);
    const addPeriod=(day,open='08:30',close='16:30')=>{const openValue=String(open).slice(0,5),closeValue=String(close).slice(0,5);const row=document.createElement('div');row.className='period-row';row.innerHTML=`<input type="time" value="${openValue}" aria-label="เวลาเปิด" required><span>ถึง</span><input type="time" value="${closeValue}" aria-label="เวลาปิด" required><button type="button" class="record-button">ลบ</button>`;row.querySelector('button').onclick=()=>row.remove();day.querySelector('.period-list').appendChild(row);};
    result.data.forEach(item=>addPeriod(wrapper.querySelector(`[data-day="${item.weekday}"]`),item.open_time,item.close_time));wrapper.querySelectorAll('[data-add-period]').forEach(button=>button.onclick=()=>addPeriod(button.closest('.schedule-day')));wrapper.querySelectorAll('[data-dialog-close]').forEach(button=>button.onclick=()=>wrapper.remove());
    wrapper.querySelector('form').onsubmit=async event=>{event.preventDefault();const intervals=[];wrapper.querySelectorAll('.schedule-day').forEach(day=>day.querySelectorAll('.period-row').forEach(row=>{const inputs=row.querySelectorAll('input');intervals.push({weekday:Number(day.dataset.day),open_time:inputs[0].value.slice(0,5),close_time:inputs[1].value.slice(0,5)})}));const error=wrapper.querySelector('[data-form-error]');error.classList.add('hidden');try{const invalid=intervals.find(item=>!item.open_time||!item.close_time||item.open_time>=item.close_time);if(invalid)throw new Error(`ช่วงเวลาของ${days[invalid.weekday-1]}ไม่ถูกต้อง เวลาเริ่มต้องน้อยกว่าเวลาสิ้นสุด`);await kqApi('save-weekly-hours',{method:'POST',body:JSON.stringify({scope_type:scopeType,scope_id:Number(scopeId),intervals})});wrapper.remove();showToast('บันทึกตารางรายสัปดาห์แล้ว');}catch(err){error.textContent=err.message;error.classList.remove('hidden')}};
  }catch(error){showToast(error.message)}
}

document.addEventListener('click',async event=>{const sync=event.target.closest('[data-hosxp-holiday-sync]');const add=event.target.closest('[data-crud-add]');const edit=event.target.closest('[data-crud-edit]');const schedule=event.target.closest('[data-schedule]');const slotRules=event.target.closest('[data-slot-rules]');if(slotRules){const record=adminCache.departments.find(item=>String(item.id)===String(slotRules.dataset.slotRules));if(record)openSlotRulesDialog(record);return}if(sync){sync.disabled=true;const original=sync.textContent;sync.textContent='กำลังซิงค์…';try{const result=await kqApi('sync-hosxp-holidays',{method:'POST',body:'{}'}),data=result.data;showToast(`ซิงค์วันหยุด ${data.holiday_count} วัน · เพิ่ม ${data.created} · อัปเดต ${data.updated}${data.skipped?` · ข้ามรายการที่ตั้งค่าเอง ${data.skipped}`:''}`);await renderCalendarPage()}catch(error){showToast(error.message)}finally{sync.disabled=false;sync.textContent=original}return}if(add){openCrudDialog(add.dataset.crudAdd);return}if(edit){const type=edit.dataset.crudEdit;const lists={building:adminCache.buildings,branch:adminCache.branches,department:adminCache.departments,service:adminCache.services,calendar:adminCache.calendars};openCrudDialog(type,(lists[type]||[]).find(item=>String(item.id)===String(edit.dataset.id))||{});return}if(schedule)openScheduleDialog(schedule.dataset.schedule,schedule.dataset.id,schedule.dataset.name);},true);

document.querySelectorAll('.nav-item').forEach(node=>{node.onclick=()=>{const view=node.dataset.view;switchView(view);if(view==='branches')renderOrganizationPage();else if(view==='services')renderServicesPage();else if(view==='calendar')renderCalendarPage();else if(view==='dashboard')loadDashboard();else hydrateView(view);};});

